end;

local mt = getrawmetatable(game);
local origin = mt.__namecall;

setreadonly(mt, false);

mt.__namecall = newcclosure(function(self: Instance, ...)
    local method: string = getnamecallmethod();
    local args = { ... };

    if self.Name == 'ResetStreak' and method == 'FireServer' then
        return nil;
    end;

    return origin(self, ...);
end);

setreadonly(mt, true);
